package com.orderflow.notification.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notification",uniqueConstraints=@UniqueConstraint(name="uq_notification_source",columnNames={"user_id","type","source_event_id"}))public class Notification{@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=64)private NotificationType type;@Column(nullable=false,length=120)private String title;@Column(nullable=false,length=500)private String message;@Column(name="source_event_id",nullable=false)private UUID sourceEventId;@Column(name="source_aggregate_id")private UUID sourceAggregateId;@Column(nullable=false)private boolean read;@Column(name="read_at")private Instant readAt;@Column(name="created_at",nullable=false)private Instant createdAt;protected Notification(){}public Notification(UUID user,NotificationType type,String title,String message,UUID event,UUID aggregate,Instant now){id=UUID.randomUUID();userId=user;this.type=type;this.title=title;this.message=message;sourceEventId=event;sourceAggregateId=aggregate;createdAt=now;}public boolean markRead(Instant at){if(read)return false;read=true;readAt=at;return true;}public UUID getId(){return id;}public UUID getUserId(){return userId;}public NotificationType getType(){return type;}public String getTitle(){return title;}public String getMessage(){return message;}public UUID getSourceEventId(){return sourceEventId;}public UUID getSourceAggregateId(){return sourceAggregateId;}public boolean isRead(){return read;}public Instant getReadAt(){return readAt;}public Instant getCreatedAt(){return createdAt;}}
